EE_4GW = "https://www.energiaestrategica.com/es/notes/que-empresas-estan-detras-de-los-4-gw-en-tramitacion-en-mexico-bess-cambia-el-mapa-y-aparecen-nuevos-protagonistas"

def P(name, kind, what_en, what_es, ev_en, ev_es, url=None, src=None):
    d = dict(name=name, kind=kind, what={"en": what_en, "es": what_es}, evidence={"en": ev_en, "es": ev_es})
    if url: d["url"] = url
    if src: d["source"] = src
    return d

